  const ref = React.useRef(null);

  React.useEffect(() => {
    const element = ref.current;
    if (!element) {
      return;
    }

    const cleanup = dropTargetForElements({
      element,
      onDrop: ({ source }) => {
        onDelete(source.data);
      },
    });

    return cleanup;
  }, [onDelete]);

  return <div ref={ref}>Drop an item here to delete</div>;
};

